import { test, expect } from '@playwright/test';

test.describe('Polling Stops When Navigating Away', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should stop polling when user navigates to another page', async ({ page }) => {
    // Intercept the polling API endpoint
    await page.route('/api/polling-endpoint', (route) => {
      route.continue();
    });

    // Verify initial polling is active
    const pollingButton = page.getByRole('button', { name: /start polling/i });
    await expect(pollingButton).toBeVisible();

    // Start polling
    await pollingButton.click();
    await expect(pollingButton).toHaveText(/stop polling/);

    // Verify polling indicator is visible
    const pollingIndicator = page.getByText(/polling active/);
    await expect(pollingIndicator).toBeVisible();

    // Navigate to another page
    const navLink = page.getByRole('link', { name: /settings/i });
    await navLink.click();
    await expect(page).toHaveURL(/.*settings/);

    // Verify polling indicator is no longer visible
    await expect(pollingIndicator).not.toBeVisible();

    // Verify polling button text has reverted
    await expect(pollingButton).toHaveText(/start polling/);

    // Navigate back to dashboard
    await page.goto('/dashboard');
    await expect(page).toHaveURL(/.*dashboard/);

    // Verify polling indicator is still not visible
    await expect(pollingIndicator).not.toBeVisible();
  });

  test('should not resume polling when navigating back to the page', async ({ page }) => {
    // Intercept the polling API endpoint
    await page.route('/api/polling-endpoint', (route) => {
      route.continue();
    });

    // Start polling
    const pollingButton = page.getByRole('button', { name: /start polling/i });
    await pollingButton.click();
    await expect(pollingButton).toHaveText(/stop polling/);

    // Verify polling indicator is visible
    const pollingIndicator = page.getByText(/polling active/);
    await expect(pollingIndicator).toBeVisible();

    // Navigate away from the page
    const navLink = page.getByRole('link', { name: /profile/i });
    await navLink.click();
    await expect(page).toHaveURL(/.*profile/);

    // Verify polling indicator is gone
    await expect(pollingIndicator).not.toBeVisible();

    // Navigate back to dashboard
    await page.goto('/dashboard');
    await expect(page).toHaveURL(/.*dashboard/);

    // Verify polling indicator is still not visible
    await expect(pollingIndicator).not.toBeVisible();

    // Verify polling button text is still "start polling"
    await expect(pollingButton).toHaveText(/start polling/);
  });
});
